{
  "gate_token": "90sRWVN9pn_Wodu9i4IvsQ",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds a map of the ruined royal city.",
      "visual_description": "A windswept hill at dusk overlooking a shattered skyline of broken spires and torn royal banners; an ink-stained coat flaps as a brass compass spins.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of every gate.",
      "visual_description": "Close-up of an oil lamp held aloft, a single glowing eye flickering inside its flame, casting long shadows over the map.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox scouts the cracked castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes creeping past enormous iron gates hanging off their hinges, key-wind tail ticking softly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver slips in through a tall stained window.",
      "visual_description": "A figure in a clear diving helmet emerging headfirst from rippling cathedral glass, coat shimmering with reflected broken city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "They regroup beneath a cursed tower.",
      "visual_description": "A leaning black tower wrapped in violet chains of light; four companions gather in its long shadow, lamp casting warm gold against the cold purple.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "Rumors of a winged beast rumble overhead.",
      "visual_description": "Silhouetted wings cross a blood-orange moon while the tin fox tilts its metal ears upward and the lamp's eye narrows.",
      "characters": ["tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "Mara refuses the tower's tempting open door.",
      "visual_description": "An ornate doorway glows invitingly with gold light and floating coins; the cartographer turns her back, compass pointing elsewhere.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "They find an official asleep on his ledger.",
      "visual_description": "A plump bureaucrat slumped over a thick ledger-pillow inside a toppled customs booth, stamped papers fluttering from his sleeves.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The lamp interrogates the dozing official.",
      "visual_description": "The oracle lamp leaning close to the snoring man's ear, its flame-eye wide; he mumbles and stamps a paper in his sleep.",
      "characters": ["oracle_lamp", "sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Armored patrols march down the avenue.",
      "visual_description": "From a low alley angle, polished greaves and halberd-butts stride past; the tin fox flattens behind a fallen royal banner of red and gold.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver dives into a puddle to scout ahead.",
      "visual_description": "The diver plunges shoulder-deep into a tiny rain puddle that reflects a distant courtyard, coat rippling like water.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Frightened townsfolk point toward the keep.",
      "visual_description": "Shuttered windows crack open; pale hands gesture toward a distant keep wreathed in green mist while Mara sketches the route in her ledger.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 13,
      "caption": "A sealed magic door blocks the inner hall.",
      "visual_description": "A massive bronze door covered in shifting runes pulsing turquoise; the tin fox sniffs at its base while the lamp reads the symbols.",
      "characters": ["tin_fox", "oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 14,
      "caption": "Glass Diver enters through the door's polished surface.",
      "visual_description": "The diver melting feet-first into the mirror-bright bronze, ripples spreading across the runes, helmet glinting as it disappears.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Inside, they wake the slumped official to unlock the seal.",
      "visual_description": "The tax collector blinking groggily as his official stamp glows; the bronze door cracks open spilling pale light into a vaulted chamber.",
      "characters": ["glass_diver", "sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The rescue party flees as alarms ring.",
      "visual_description": "Bells swinging in shattered belfries; the four companions race down a colonnade as red lanterns ignite one by one behind them.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the long stone bridge.",
      "visual_description": "A narrow moonlit bridge over a black chasm; the tin fox skids ahead, lamp swinging wildly, ink-stained coat streaming behind Mara.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "Beyond the bridge, the ruined city falls behind.",
      "visual_description": "Dawn breaking over distant hills; the companions silhouetted at the bridge's far end, the broken skyline shrinking under a pale pink sky.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

